17	package org.springframework.samples.petclinic.rest.validation;
18	
19	import java.util.Comparator;
20	import java.util.Objects;
21	
22	import org.springframework.samples.petclinic.model.Owner;
23	import org.springframework.samples.petclinic.service.ClinicService;
24	import org.springframework.stereotype.Component;
25	import org.springframework.util.StringUtils;
26	
27	/**
28	 * Detects a soft match between a newly created owner and an existing one: an owner that is not a
29	 * hard {@link DuplicateOwnerValidator duplicate} but shares an existing owner's last name and
30	 * postcode while holding a different telephone. Unlike the duplicate validator this never rejects
31	 * the create; it merely reports the existing owner so the caller can flag the new one as a possible
32	 * duplicate.
33	 */
34	@Component
35	public class PossibleDuplicateDetector {
36	
37	    private final ClinicService clinicService;
38	
39	    public PossibleDuplicateDetector(ClinicService clinicService) {
40	        this.clinicService = clinicService;
41	    }
42	
43	    /**
44	     * @param owner the owner being created, with its telephone already normalized
45	     * @return the id of the lowest-id existing owner that shares this owner's last name and
46	     * postcode but holds a different telephone, or {@code null} when there is no such match
47	     */
48	    public Integer findPossibleDuplicate(Owner owner) {
49	        if (!StringUtils.hasText(owner.getPostcode())) {
50	            return null;
51	        }
52	        return this.clinicService.findOwnerByLastName(owner.getLastName()).stream()
53	            .filter(existing -> !existing.isDeleted())
54	            .filter(existing -> existing.getLastName().equalsIgnoreCase(owner.getLastName()))
55	            .filter(existing -> owner.getPostcode().equals(existing.getPostcode()))
56	            .filter(existing -> !Objects.equals(owner.getTelephone(), existing.getTelephone()))
57	            .map(Owner::getId)
58	            .filter(Objects::nonNull)
59	            .min(Comparator.naturalOrder())
60	            .orElse(null);
61	    }
62	}
