376	    }
377	
378	    /**
379	     * The owner's membership level, a number from 1 to 4 derived from the owner's
380	     * {@link #getMembershipPoints() membership points}: 1 for 0-1 points, 2 for 2-3, 3 for 4-5, and
381	     * 4 for 6 or more. The level is then held to its {@link #getMembershipLevelCap() cap} (one above
382	     * the highest level among the owner's household members at creation), so a new owner cannot rank
383	     * more than one level above their household. An uncapped owner keeps the derived level.
384	     */
385	    public Integer getMembershipLevel() {
386	        int level = derivedMembershipLevel();
387	        if (this.membershipLevelCap != null && level > this.membershipLevelCap) {
388	            return this.membershipLevelCap;
389	        }
