351	     * the owner earns 2 points when an email address is present, 1 point when this owner has no
352	     * namesakes ({@code namesakeCount} is 0), 2 points for a household of 3 or more members, and 3
353	     * points once the owner's {@link #getTenureFiscalYears() tenure} spans at least one full fiscal
354	     * year (the registration and current dates fall in different fiscal years).
355	     */
356	    public Integer getMembershipPoints() {
357	        int points = 0;
358	        boolean hasEmail = this.email != null && !this.email.isEmpty();
359	        if (hasEmail) {
360	            points += 2;
361	        }
362	        boolean unique = this.namesakeCount != null && this.namesakeCount == 0;
363	        if (unique) {
364	            points += 1;
365	        }
366	        boolean sharedHousehold = this.householdSize != null && this.householdSize >= 3;
367	        if (sharedHousehold) {
368	            points += 2;
369	        }
370	        Long tenureFiscalYears = getTenureFiscalYears();
371	        boolean tenured = tenureFiscalYears != null && tenureFiscalYears >= 1;
372	        if (tenured) {
373	            points += 3;
