393	    private int derivedMembershipLevel() {
394	        int points = getMembershipPoints();
395	        if (points >= 6) {
396	            return 4;
397	        }
398	        if (points >= 4) {
399	            return 3;
400	        }
401	        if (points >= 2) {
402	            return 2;
403	        }
404	        return 1;
