22	/**
23	 * SHA-256 helper shared across the domain: the single place that computes a lower-case hex digest of
24	 * a value's UTF-8 bytes, so every derived identifier hashes the same way.
25	 */
26	public final class Sha256 {
27	
28	    private Sha256() {
29	    }
30	
31	    /**
32	     * @param value the text to digest
33	     * @return the lower-case hex SHA-256 of the UTF-8 bytes of {@code value}
34	     */
35	    public static String hex(String value) {
36	        try {
37	            byte[] digest = MessageDigest.getInstance("SHA-256")
38	                .digest(value.getBytes(StandardCharsets.UTF_8));
39	            StringBuilder hex = new StringBuilder(digest.length * 2);
40	            for (byte b : digest) {
41	                hex.append(String.format("%02x", b));
42	            }
43	            return hex.toString();
44	        }
45	        catch (NoSuchAlgorithmException ex) {
46	            throw new IllegalStateException("SHA-256 is required but unavailable", ex);
47	        }
48	    }
49	}
