17	package org.springframework.samples.petclinic.rest.assignment;
18	
19	import org.springframework.samples.petclinic.model.Owner;
20	import org.springframework.samples.petclinic.rest.validation.HouseholdKey;
21	import org.springframework.stereotype.Component;
22	
23	/**
24	 * Computes the size of an owner's household. Because the household is keyed on (last name, postcode)
25	 * every owner already carries the shared {@code householdId}, so there is nothing to link: the size
26	 * is simply the joining owner plus every existing owner in the same {@link HouseholdKey household}.
27	 */
28	@Component
29	public class HouseholdSizeCalculator {
30	
31	    private final HouseholdMembers householdMembers;
32	
33	    public HouseholdSizeCalculator(HouseholdMembers householdMembers) {
34	        this.householdMembers = householdMembers;
35	    }
36	
37	    /**
38	     * @param owner the owner being created, not yet saved
39	     * @return the number of members in the household once {@code owner} joins, counting the joining
40	     * owner and every existing owner with the same last name and postcode
41	     */
42	    public int size(Owner owner) {
43	        return this.householdMembers.existing(owner).size() + 1;
44	    }
45	}
