26	import org.springframework.samples.petclinic.service.ClinicService;
27	import org.springframework.stereotype.Component;
28	
29	/**
30	 * Builds an owner's {@code customerCode}, formatted {@code '<REGION>-<HASH8>'} where REGION is the
31	 * region derived from the postcode (see {@link Regions#regionOfPostcode(String)}) and HASH8 is the
32	 * first 8 upper-case hex characters of SHA-256 over the normalized telephone concatenated with the
33	 * last name (e.g. {@code 'NSW-1A2B3C4D'}).
34	 *
35	 * <p>When the formatted code collides with an existing owner's {@code customerCode}, {@code '-<n>'}
36	 * is appended with the smallest {@code n} of 2 or more that makes it unique, so distinct owners
37	 * always receive distinct customer codes.
38	 */
39	@Component
40	public class CustomerCodeGenerator {
41	
42	    private static final int HASH_LENGTH = 8;
43	
44	    private final ClinicService clinicService;
45	
46	    public CustomerCodeGenerator(ClinicService clinicService) {
47	        this.clinicService = clinicService;
48	    }
49	
50	    /**
51	     * @param postcode  the owner's postcode, used to derive the REGION prefix
52	     * @param telephone the owner's normalized telephone, hashed with the last name
53	     * @param lastName  the owner's last name, hashed with the telephone
54	     * @return the formatted customer code, de-duplicated against existing owners
55	     */
56	    public String generate(String postcode, String telephone, String lastName) {
57	        String region = Regions.regionOfPostcode(postcode);
58	        String hash8 = Sha256.hex(telephone + lastName).substring(0, HASH_LENGTH).toUpperCase(Locale.ROOT);
59	        return deduplicate(region + "-" + hash8);
60	    }
61	
62	    /**
63	     * Return {@code base} if no existing owner already uses it; otherwise append {@code '-<n>'}
64	     * with the smallest {@code n >= 2} that is not yet taken.
65	     */
66	    private String deduplicate(String base) {
67	        Set<String> existing = existingCustomerCodes();
68	        if (!existing.contains(base)) {
69	            return base;
70	        }
71	        for (int n = 2; ; n++) {
72	            String candidate = base + "-" + n;
73	            if (!existing.contains(candidate)) {
74	                return candidate;
75	            }
76	        }
77	    }
78	
79	    private Set<String> existingCustomerCodes() {
80	        Set<String> codes = new HashSet<>();
81	        for (Owner owner : this.clinicService.findAllOwners()) {
82	            String code = owner.getCustomerCode();
83	            if (code != null) {
84	                codes.add(code);
85	            }
86	        }
87	        return codes;
88	    }
89	}
