26	/**
27	 * Rejects an owner whose email address belongs to a known disposable-email provider. Expects the
28	 * already-normalized (trimmed, lower-cased) email produced by {@link EmailNormalizer}; an absent
29	 * email passes untouched.
30	 */
31	@Component
32	public class DisposableEmailDomainValidator {
33	
34	    private static final Set<String> BLOCKED_DOMAINS =
35	        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
36	
37	    /**
38	     * @param email the normalized email address, or {@code null} when none was supplied
39	     * @throws DisposableEmailDomainException if the email's domain is on the blocklist
40	     */
