42	        if (!StringUtils.hasText(email)) {
43	            return;
44	        }
45	        String domain = email.substring(email.indexOf('@') + 1).toLowerCase(Locale.ROOT);
46	        if (BLOCKED_DOMAINS.contains(domain)) {
47	            throw new DisposableEmailDomainException(email);
48	        }
49	    }
50	}
