47	        if (telephone == null) {
48	            throw new InvalidTelephoneException(null);
49	        }
50	        String cleaned = telephone.trim().replaceAll(FORMATTING_CHARS, "");
51	        String digits;
52	        if (cleaned.startsWith("+")) {
53	            digits = cleaned.substring(1);
54	        } else {
55	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
56	            digits = DEFAULT_COUNTRY_CODE + national;
57	        }
58	        if (!digits.matches("\\d{" + MIN_DIGITS + "," + MAX_DIGITS + "}")) {
59	            throw new InvalidTelephoneException(telephone);
60	        }
61	        requireValidNationalLength(digits, telephone);
62	        return "+" + digits;
63	    }
